# Generated by build.py from recipe.yml for recipe sftp-upload-a-batch-and-verify-it. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p batch
printf '%s\n' 'release notes' > batch/notes.txt
cat > batch/config.ini <<'EOF'
[app]
name = demo
EOF
cat > batch/data.csv <<'EOF'
id,name
1,a
2,b
EOF
cat > makeblobs.sh <<'EOF'
head -c 1500 /dev/zero > batch/blob.bin
mkdir -p short
head -c 1000 /dev/zero > short/blob.bin
EOF
cat > upload.sh <<'EOF'
#!/bin/sh
# Usage: sh upload.sh PORT DIR [NAME...]
# Uploads the named files of DIR (all of them when none is named) to /inbox/ on a surl
# whose host key is pinned: the fingerprint comes from host_key.pub, so a different key is refused.
set -e
port=$1; dir=$2; shift 2
[ $# -gt 0 ] || set -- $(ls "$dir")
pin=$(ssh-keygen -l -f host_key.pub | cut -d' ' -f2 | sed 's/^SHA256://')
# One curl for the whole batch: -T takes a glob, and a URL ending in / keeps each file's name.
list=$(echo "$@" | tr ' ' ',')
curl -s -S --hostpubsha256 "$pin" -u alice:s3cret --ftp-create-dirs \
  -T "$dir/{$list}" "sftp://127.0.0.1:$port/inbox/"
EOF
cat > compare.sh <<'EOF'
#!/bin/sh
# Usage: sh compare.sh PORT DIR
# Lists /inbox/ on the server and compares every name and size with the files of DIR.
set -e
port=$1; dir=$2
pin=$(ssh-keygen -l -f host_key.pub | cut -d' ' -f2 | sed 's/^SHA256://')
for name in $(ls "$dir"); do echo "$name $(wc -c < "$dir/$name" | tr -d ' ')"; done | LC_ALL=C sort > local.txt
curl -s -S --hostpubsha256 "$pin" -u alice:s3cret "sftp://127.0.0.1:$port/inbox/" > listing.txt
awk '{print $NF, $5}' listing.txt | LC_ALL=C sort > remote.txt
if diff local.txt remote.txt > diff.txt; then
  echo "all $(wc -l < local.txt | tr -d ' ') files match"
  cat remote.txt
else
  echo "MISMATCH"
  cat diff.txt
  exit 1
fi
EOF
ssh-keygen -q -t rsa -b 3072 -N "" -f host_key
sh makeblobs.sh
surl --hostkey host_key --user alice:s3cret --allow-uploads --list-directories sftp://127.0.0.1:8080/ &
sleep 1
sh upload.sh 8080 batch && sh compare.sh 8080 batch
kill $(jobs -p)
